pre.code:
xAxis: {
  type: 'category',
  data: ['Web', 'API', 'Database', 'Cache', 'Search']
},
yAxis: { type: 'value', name: 'ms' },
series: [{
  name: 'Response Time',
  type: 'boxplot',
  // [min, Q1, median, Q3, max]
  data: [
    [25,  45,  68,  120,  280],
    [15,  30,  48,   85,  190],
    [80, 150, 220,  350,  600],
    [ 5,   8,  12,   18,   35],
    [120,200, 280,  420,  780]
  ]
}]

viz.option:
option = {
  title: {
    text: 'Response Time Distribution by Service (ms)',
    left: 'center'
  },
  tooltip: {
    trigger: 'item',
    axisPointer: { type: 'shadow' },
    formatter: function (param) {
      return [
        param.name,
        'Max: '    + param.data[5],
        'Q3: '     + param.data[4],
        'Median: ' + param.data[3],
        'Q1: '     + param.data[2],
        'Min: '    + param.data[1]
      ].join('
');
    }
  },
  grid: { left: '8%', right: '5%', bottom: '10%' },
  xAxis: {
    type: 'category',
    data: ['Web Server', 'API Gateway', 'Database', 'Cache', 'Search'],
    boundaryGap: true,
    nameGap: 30,
    splitArea: { show: true },
    axisLabel: { rotate: 15 },
    splitLine: { show: false }
  },
  yAxis: {
    type: 'value',
    name: 'Response time (ms)',
    splitArea: { show: true }
  },
  series: [
    {
      name: 'Response Time',
      type: 'boxplot',
      data: [
        [25,  45,  68,  120,  280],
        [15,  30,  48,   85,  190],
        [80, 150, 220,  350,  600],
        [5,    8,  12,   18,   35],
        [120, 200, 280, 420,  780]
      ],
      tooltip: {
        formatter: function (param) {
          return [
            param.name,
            'Max: '    + param.data[5],
            'Q3: '     + param.data[4],
            'Median: ' + param.data[3],
            'Q1: '     + param.data[2],
            'Min: '    + param.data[1]
          ].join('  |  ');
        }
      }
    }
  ]
};
